import{_ as n,o as a,c as i,a3 as t}from"./chunks/framework.BlfGB29P.js";const r="/images/logic-studio/user-guide/function-plan-walkthrough-de.jpg",p=JSON.parse('{"title":"Funktionsplan","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/function-plan.md","filePath":"projects/logic-studio/user-guide/function-plan.md","lastUpdated":1795179952000}'),o={name:"projects/logic-studio/user-guide/function-plan.md"};function s(d,e,u,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="funktionsplan" tabindex="-1">Funktionsplan <a class="header-anchor" href="#funktionsplan" aria-label="Permalink to &quot;Funktionsplan&quot;">​</a></h1><h2 id="ein-signal-im-funktionsplan-umkehren" tabindex="-1">Ein Signal im Funktionsplan umkehren <a class="header-anchor" href="#ein-signal-im-funktionsplan-umkehren" aria-label="Permalink to &quot;Ein Signal im Funktionsplan umkehren&quot;">​</a></h2><h3 id="_1-plan-offnen-und-bausteine-hinzufugen" tabindex="-1">1. Plan öffnen und Bausteine hinzufügen <a class="header-anchor" href="#_1-plan-offnen-und-bausteine-hinzufugen" aria-label="Permalink to &quot;1. Plan öffnen und Bausteine hinzufügen&quot;">​</a></h3><p>Öffne <strong>Funktionsplan</strong> im Projektbaum. Suche links nacheinander <code>STATE_IN</code>, <code>NOT</code> und <code>STATE_OUT</code>. Klicke jeweils auf den Baustein, um ihn einzufügen. Ziehe die Bausteine an ihrer Kopfzeile in dieser Reihenfolge von links nach rechts.</p><h3 id="_2-eingang-konfigurieren" tabindex="-1">2. Eingang konfigurieren <a class="header-anchor" href="#_2-eingang-konfigurieren" aria-label="Permalink to &quot;2. Eingang konfigurieren&quot;">​</a></h3><p>Öffne über das Zahnrad die Eigenschaften von <code>STATE_IN</code>. Trage die Entitäts-ID deines Sensors oder Testhelfers ein. Im Bild ist das <code>binary_sensor.bewegung</code>. Stelle <strong>Signaltyp</strong> auf <code>BOOL</code> und <strong>Demo-Eingang (nur Simulation)</strong> auf <code>TRUE</code>.</p><h3 id="_3-ausgang-konfigurieren" tabindex="-1">3. Ausgang konfigurieren <a class="header-anchor" href="#_3-ausgang-konfigurieren" aria-label="Permalink to &quot;3. Ausgang konfigurieren&quot;">​</a></h3><p>Öffne die Eigenschaften von <code>STATE_OUT</code>. Trage eine passende Ziel-ID ein. Im Bild ist es <code>light.flur</code>. Lass den <strong>Ausgangsmodus</strong> auf <code>BOOL</code>. Ein BOOL-Signal hat genau zwei Werte, <code>TRUE</code> und <code>FALSE</code>.</p><h3 id="_4-anschlusse-verbinden" tabindex="-1">4. Anschlüsse verbinden <a class="header-anchor" href="#_4-anschlusse-verbinden" aria-label="Permalink to &quot;4. Anschlüsse verbinden&quot;">​</a></h3><p>Ziehe vom runden Ausgangspunkt <strong>Q</strong> von <code>STATE_IN</code> zum Eingangspunkt <strong>IN</strong> von <code>NOT</code>. Ziehe dann von <strong>OUT</strong> an <code>NOT</code> zu <strong>IN</strong> an <code>STATE_OUT</code>. Oberhalb der Zeichenfläche sollten drei Bausteine und zwei Verbindungen stehen.</p><h3 id="_5-simulation-ausfuhren" tabindex="-1">5. Simulation ausführen <a class="header-anchor" href="#_5-simulation-ausfuhren" aria-label="Permalink to &quot;5. Simulation ausführen&quot;">​</a></h3><p>Klicke oben auf <strong>Simulation</strong> (Kolbensymbol). Am Eingang siehst du <code>Demo: true</code>. <code>NOT</code> kehrt den Wert um. Bei <code>STATE_OUT</code> steht deshalb <code>Demo: false</code>. Die Simulation verwendet Demowerte und schaltet die Leuchte nicht.</p><h3 id="_6-gegenprobe-machen" tabindex="-1">6. Gegenprobe machen <a class="header-anchor" href="#_6-gegenprobe-machen" aria-label="Permalink to &quot;6. Gegenprobe machen&quot;">​</a></h3><p>Setze den Demo-Eingang auf <code>FALSE</code> und klicke erneut auf <strong>Simulation</strong>. Jetzt ist der Ausgang <code>true</code>. Mit <strong>Simulation zurücksetzen</strong> startest du den Simulationszustand neu. Wenn du den Plan behalten möchtest, speichere das Projekt.</p><p><a href="/images/logic-studio/user-guide/function-plan-walkthrough-de.jpg"><img src="'+r+'" alt="Funktionsplan mit STATE_IN, NOT und STATE_OUT. Die Simulation zeigt true am Eingang und false am Ausgang."></a></p><p>Wenn eine Verbindung abgelehnt wird, prüfe die Signaltypen. Falls die Simulation eine fehlende Entitäts-ID meldet, überprüfe die Eigenschaften von Eingang und Ausgang. Nutze für dieses Beispiel das Simulationssymbol. <strong>Play</strong> in der Projektleiste startet die Runtime.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="zeichenflache" tabindex="-1">Zeichenfläche <a class="header-anchor" href="#zeichenflache" aria-label="Permalink to &quot;Zeichenfläche&quot;">​</a></h3><p>Bausteine ziehen, verschieben und verbinden. Mit Zoom und Einpassen behältst du den Überblick.</p><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to &quot;Parameter&quot;">​</a></h3><p>Wähle den Baustein und stelle etwa die Zeit eines Timers oder den Sollwert eines Zählers ein.</p><h3 id="ha-ein-und-ausgange" tabindex="-1">HA-Ein- und Ausgänge <a class="header-anchor" href="#ha-ein-und-ausgange" aria-label="Permalink to &quot;HA-Ein- und Ausgänge&quot;">​</a></h3><p>Ordne eine Entität für das Eingangssignal und bei Bedarf eine freigegebene HA-Aktion für den Ausgang zu.</p><h3 id="simulation" tabindex="-1">Simulation <a class="header-anchor" href="#simulation" aria-label="Permalink to &quot;Simulation&quot;">​</a></h3><p>Schalte Eingangswerte um und verfolge die Signale an den Anschlüssen.</p><h3 id="haltepunkt-und-einzelschritt" tabindex="-1">Haltepunkt und Einzelschritt <a class="header-anchor" href="#haltepunkt-und-einzelschritt" aria-label="Permalink to &quot;Haltepunkt und Einzelschritt&quot;">​</a></h3><p>Halte die Simulation an und gehe einen Zyklus weiter, um die Werte zu prüfen.</p><h3 id="anordnen-und-anheften" tabindex="-1">Anordnen und Anheften <a class="header-anchor" href="#anordnen-und-anheften" aria-label="Permalink to &quot;Anordnen und Anheften&quot;">​</a></h3><p>Ordne den Plan automatisch an. Angeheftete Bausteine behalten dabei ihre Position.</p><h3 id="play-und-live-diagnose" tabindex="-1">Play und Live-Diagnose <a class="header-anchor" href="#play-und-live-diagnose" aria-label="Permalink to &quot;Play und Live-Diagnose&quot;">​</a></h3><p>Starte den gespeicherten Plan. Die Diagnose zeigt Werte und Fehler des laufenden Plans.</p><h3 id="zahler-und-merker-speichern" tabindex="-1">Zähler und Merker speichern <a class="header-anchor" href="#zahler-und-merker-speichern" aria-label="Permalink to &quot;Zähler und Merker speichern&quot;">​</a></h3><p>Aktiviere die Option, wenn diese Werte einen App-Neustart überstehen sollen. Eine Änderung am Plan kann den Speicher zurücksetzen.</p><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn die Verbindung nicht angenommen wird, vergleiche die Typen beider Anschlüsse. Ein Zahlenausgang passt nicht an jeden Eingang.</p>',35)])])}const f=n(o,[["render",s]]);export{p as __pageData,f as default};
